Ah, a checkout flow. Like the streams of time itself - must flow properly or everything gets tangled. Here's how I'd sweep this path clean:

```typescript
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { axe, toHaveNoViolations } from 'jest-axe';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Arrange - the sweeping begins before the visitors arrive
const mockCart = {
  items: [{ id: '1', name: 'Yak Butter', price: 12.99 }],
  total: 12.99,
  clearCart: vi.fn(),
};

const mockPayment = {
  processPayment: vi.fn().mockResolvedValue({ orderId: 'ORD-123' }),
};

const renderCheckout = () => {
  return render(
    <CartContext.Provider value={mockCart}>
      <PaymentContext.Provider value={mockPayment}>
        <Checkout onComplete={vi.fn()} onCancel={vi.fn()} />
      </PaymentContext.Provider>
    </CartContext.Provider>
  );
};

describe('Checkout - Happy Path', () => {
  it('completes full checkout flow from shipping to confirmation', async () => {
    const user = userEvent.setup();
    renderCheckout();

    // Shipping step
    await user.type(screen.getByLabelText(/street address/i), '123 Oi Dong');
    await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
    await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
    await user.type(screen.getByLabelText(/zip code/i), '12345');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
    await user.type(screen.getByLabelText(/expiry/i), '12/25');
    await user.type(screen.getByLabelText(/cvv/i), '123');
    await user.type(screen.getByLabelText(/name on card/i), 'Lu-Tze');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/yak butter/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByRole('status')).toHaveTextContent(/ORD-123/);
    });
  });
});

describe('Checkout - Validation', () => {
  it('displays error when ZIP code is invalid', async () => {
    const user = userEvent.setup();
    renderCheckout();

    await user.type(screen.getByLabelText(/zip code/i), 'bad');
    await user.click(screen.getByRole('button', { name: /continue/i }));

    expect(screen.getByRole('alert')).toHaveTextContent(/valid zip/i);
    expect(screen.getByLabelText(/zip code/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

describe('Checkout - Error States', () => {
  it('shows payment failure and allows retry', async () => {
    mockPayment.processPayment.mockRejectedValueOnce(new Error('Card declined'));
    // ...navigate to review, click place order

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });
    expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
  });
});

describe('Checkout - Edge Cases', () => {
  it('shows empty cart message when no items', () => {
    render(/* cart with empty items */);
    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });
});

describe('Checkout - Accessibility', () => {
  it('has no accessibility violations', async () => {
    const { container } = renderCheckout();
    expect(await axe(container)).toHaveNoViolations();
  });
});
```

